    building:'<rect x="4" y="3" width="16" height="18" rx="1"/><path d="M8 7h2m4 0h2M8 11h2m4 0h2M8 15h2m4 0h2M10 21v-4h4v4"/>',
    shield:'<path d="m12 2 8 3v6c0 5-3.4 8.7-8 11-4.6-2.3-8-6-8-11V5l8-3Z"/><path d="m9 12 2 2 4-4"/>',
    gauge:'<path d="M4 16a9 9 0 1 1 16 0l-2 4H6l-2-4Z"/><path d="m12 13 4-4M8 17h8"/>',
