    wrench:'<path d="M14 6a5 5 0 0 0-6.5 6.5L3 17l4 4 4.5-4.5A5 5 0 0 0 18 10l-4 1-3-3 1-4Z"/>',
    door:'<path d="M5 21V3h14v18H5Zm7-18v18M9 12h.01"/>',
