  const imageTag=(name,alt='',cls='',lazy=true)=>`<img src="${img(name)}" alt="${alt}" class="${cls}" ${lazy?'loading="lazy"':'fetchpriority="high"'} />`;
  const eyebrow=(text,light=false)=>`<span class="eyebrow ${light?'light':''}"><span class="eyebrow-dash"></span>${text}</span>`;
