    const automation=D.autoServices.map((s,i)=>`<article class="reference-service"><div class="reference-service-icon">${ic(s.icon,25)}</div><h3>${tr(s.title)}</h3><p>${tr(s.desc)}</p></article>`).join('');
    const works=D.projects.slice(0,8).map(x=>`<button class="reference-work" type="button" data-project="${x.id}" aria-label="${P('View project','عرض المشروع')}: ${tr(x.title)}">${imageTag(x.img,tr(x.title))}<span class="reference-work-cover">${ic('plus',23)}</span></button>`).join('');
    const articles=D.insights.slice(0,4).map((x,i)=>`<article class="reference-news-card"><button type="button" data-insight="${x.id}" class="reference-news-image">${imageTag(x.img,tr(x.title))}</button><div class="reference-news-copy"><small>${tr(x.type)}</small><h3>${tr(x.title)}</h3><p>${tr(x.teaser)}</p><button class="reference-read-more" type="button" data-insight="${x.id}">${P('READ MORE','اقرأ المزيد')} ${ic('arrow',14)}</button></div></article>`).join('');
